import{_ as e,a0 as a,w as r,s as p,I as n,x as i,a1 as o,A as s,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何在一個 U 盤上安裝多個 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"如何在一個 U 盤上安裝多個 Linux 發行版 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在一個 U 盤上安裝多個 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在一個 U 盤上安裝多個 Linux 發行版 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171008 How to Install Multiple Linux Distributions on One USB","title":"如何在一個 U 盤上安裝多個 Linux 發行版","tag":"201710","desc":""},"relativePath":"201710/20171008 How to Install Multiple Linux Distributions on One USB.md","filePath":"[post].md"}'),d={name:"201710/20171008 How to Install Multiple Linux Distributions on One USB.md"};function x(m,t,b,U,f,L){const l=a("Link");return r(),p("div",null,[t[19]||(t[19]=n("h1",{id:"如何在一個-u-盤上安裝多個-linux-發行版",tabindex:"-1"},[i("如何在一個 U 盤上安裝多個 Linux 發行版 "),n("a",{class:"header-anchor",href:"#如何在一個-u-盤上安裝多個-linux-發行版","aria-label":"Permalink to “如何在一個 U 盤上安裝多個 Linux 發行版”"},"​")],-1)),t[20]||(t[20]=n("blockquote",null,[n("p",null,[i("概要：本教程介紹如何在一個 U 盤上安裝多個 Linux 發行版。這樣，你可以在單個 U 盤上享受多個"),n("ruby",null,[i("現場版"),n("rt",null,"live")]),i(" Linux 發行版了。")])],-1)),t[21]||(t[21]=n("p",null,"我喜歡通過 U 盤嘗試不同的 Linux 發行版。它讓我可以在真實的硬件上測試操作系統，而不是虛擬化的環境中。此外，我可以將 USB 插入任何系統（比如 Windows 系統），做任何我想要的事情，以及享受相同的 Linux 體驗。而且，如果我的系統出現問題，我可以使用 U 盤恢復！",-1)),n("p",null,[t[1]||(t[1]=i("創建單個",-1)),o(l,{href:"https://itsfoss.com/create-live-usb-of-ubuntu-in-windows/"},{default:s(()=>[...t[0]||(t[0]=[i("可啓動的現場版 Linux USB",-1)])]),_:1}),t[2]||(t[2]=i(" 很簡單，你只需下載一個 ISO 文件並將其刻錄到 U 盤。但是，如果你想嘗試多個 Linux 發行版呢？你可以使用多個 U 盤，也可以覆蓋同一個 U 盤以嘗試其他 Linux 發行版。但這兩種方法都不是很方便。",-1))]),t[22]||(t[22]=u('<p>那麼，有沒有在單個 U 盤上安裝多個 Linux 發行版的方式呢？我們將在本教程中看到如何做到這一點。</p><h3 id="如何創建有多個-linux-發行版的可啓動-usb" tabindex="-1">如何創建有多個 Linux 發行版的可啓動 USB <a class="header-anchor" href="#如何創建有多個-linux-發行版的可啓動-usb" aria-label="Permalink to “如何創建有多個 Linux 發行版的可啓動 USB”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2017/10/multiple-linux-on-one-usb-800x450.jpg" alt="How to install multiple linux distributions on a single USB"></p><p>我們有一個工具正好可以做到_在單個 U 盤上保留多個 Linux 發行版_。你所需要做的只是選擇要安裝的發行版。在本教程中，我們將介紹_如何在 U 盤中安裝多個 Linux 發行版_用於<ruby>現場會話<rt>live session</rt></ruby>。</p><p>要確保你有一個足夠大的 U 盤，以便在它上面安裝多個 Linux 發行版，一個 8 GB 的 U 盤應該足夠用於三四個 Linux 發行版。</p><h4 id="步驟-1" tabindex="-1">步驟 1 <a class="header-anchor" href="#步驟-1" aria-label="Permalink to “步驟 1”">​</a></h4>',6)),n("p",null,[o(l,{href:"http://multibootusb.org/"},{default:s(()=>[...t[3]||(t[3]=[i("MultiBootUSB",-1)])]),_:1}),t[4]||(t[4]=i(" 是一個自由、開源的跨平台應用程序，允許你創建具有多個 Linux 發行版的 U 盤。它還支持在任何時候卸載任何發行版，以便你回收驅動器上的空間用於另一個發行版。",-1))]),t[23]||(t[23]=n("p",null,"下載 .deb 包並雙擊安裝。",-1)),n("p",null,[o(l,{href:"https://github.com/mbusb/multibootusb/releases/download/v8.8.0/python3-multibootusb_8.8.0-1_all.deb"},{default:s(()=>[...t[5]||(t[5]=[i("下載 MultiBootUSB",-1)])]),_:1})]),t[24]||(t[24]=u('<h4 id="步驟-2" tabindex="-1">步驟 2 <a class="header-anchor" href="#步驟-2" aria-label="Permalink to “步驟 2”">​</a></h4><p>推薦的文件系統是 FAT32，因此在創建多引導 U 盤之前，請確保格式化 U 盤。</p><h4 id="步驟-3" tabindex="-1">步驟 3 <a class="header-anchor" href="#步驟-3" aria-label="Permalink to “步驟 3”">​</a></h4><p>下載要安裝的 Linux 發行版的 ISO 鏡像。</p><h4 id="步驟-4" tabindex="-1">步驟 4 <a class="header-anchor" href="#步驟-4" aria-label="Permalink to “步驟 4”">​</a></h4><p>完成這些後，啓動 MultiBootUSB。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/1.png" alt="MultiBootUSB"></p><p>主屏幕要求你選擇 U 盤和你打算放到 U 盤上的 Linux 發行版鏡像文件。</p><p>MultiBootUSB 支持 Ubuntu、Fedora 和 Debian 發行版的持久化，這意味着對 Linux 發行版的現場版本所做的更改將保存到 USB 上。</p><p>你可以通過拖動 MultiBootUSB 選項卡下的滑塊來選擇持久化大小。持久化為你提供了在運行時將更改保存到 U 盤的選項。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/2-1.png" alt="MultiBootUSB persistence storage"></p><h4 id="步驟-5" tabindex="-1">步驟 5 <a class="header-anchor" href="#步驟-5" aria-label="Permalink to “步驟 5”">​</a></h4><p>單擊“安裝發行版”選項並繼續安裝。在顯示成功的安裝消息之前，需要一些時間才能完成。</p><p>你現在可以在已安裝部分中看到發行版了。對於另外的操作系統，重複該過程。這是我安裝 Ubuntu 16.10 和 Fedora 24 後的樣子。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/3.png" alt="MultiBootSystem with Ubuntu and Fedora"></p><h4 id="步驟-6" tabindex="-1">步驟 6 <a class="header-anchor" href="#步驟-6" aria-label="Permalink to “步驟 6”">​</a></h4><p>下次通過 USB 啓動時，我可以選擇任何一個發行版。</p><p><img src="https://itsfoss.com/wp-content/uploads/2017/09/VirtualBox_Ubuntu1610_23_09_2017_14_16_05-1.png" alt="Boot Menu"></p><p>只要你的 U 盤允許，你可以添加任意數量的發行版。要刪除發行版，請從列表中選擇它，然後單擊卸載發行版。</p><h3 id="最後的話" tabindex="-1">最後的話 <a class="header-anchor" href="#最後的話" aria-label="Permalink to “最後的話”">​</a></h3><p>MultiBootUSB 真的很便於在 U 盤上安裝多個 Linux 發行版。只需點擊幾下，我就有兩個我最喜歡的操作系統的工作盤了，我可以在任何系統上啓動它們。</p><p>如果你在安裝或使用 MultiBootUSB 時遇到任何問題，請在評論中告訴我們。</p><hr>',23)),n("p",null,[t[7]||(t[7]=i("via: ",-1)),o(l,{href:"https://itsfoss.com/multiple-linux-one-usb/"},{default:s(()=>[...t[6]||(t[6]=[i("https://itsfoss.com/multiple-linux-one-usb/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=i("作者：",-1)),o(l,{href:"https://itsfoss.com/author/ambarish/"},{default:s(()=>[...t[8]||(t[8]=[i("Ambarish Kumar",-1)])]),_:1}),t[12]||(t[12]=i(" 譯者：",-1)),o(l,{href:"https://github.com/geekpi"},{default:s(()=>[...t[9]||(t[9]=[i("geekpi",-1)])]),_:1}),t[13]||(t[13]=i(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:s(()=>[...t[10]||(t[10]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=i("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[14]||(t[14]=[i("LCTT",-1)])]),_:1}),t[17]||(t[17]=i(" 原創編譯，",-1)),o(l,{href:"https://linux.cn/"},{default:s(()=>[...t[15]||(t[15]=[i("Linux中國",-1)])]),_:1}),t[18]||(t[18]=i(" 榮譽推出",-1))])])}const T=e(d,[["render",x]]);export{S as __pageData,T as default};
